// Lab型別：已驗證來源的完整快照，不是廠商API。
sealed class LabVersionState {
    private readonly object _gate = new();
    private long _version = -1;
    private string _value = "Unknown";
    public void Apply(LabVersionEvent e) {
        lock (_gate) {
            if (e.Version <= _version) return;
            _version = e.Version;
            _value = e.Value;
        }
    }
    public (long Version, string Value) Snapshot() {
        lock (_gate) return (_version, _value);
    }
}
record LabVersionEvent(long Version, string Value);

await _slots.WaitAsync(token);
try { await SendIndependentWorkAsync(token); }
finally { _slots.Release(); }
// 若 WaitAsync 丟取消例外，尚未進入 try，不能亂 Release。

